import type { PropType } from "vue";
import { defineComponent, onMounted, reactive } from "vue";
import { LayoutLoadingIcon } from "../../components/layout-loading-icon/layout-loading-icon";
import { useCsNamespace } from "../../hooks";
import { useLayoutPrefix } from "../../plugins/layout-plugin/layout/utils/plugin-utils";

export const LayoutFrameLoading = defineComponent({
  name: "LayoutFrameLoading",
  props: {
    pluginManager: {
      type: Object as PropType<any>,
      required: true,
    },
  },
  setup() {
    const ns = useCsNamespace("layout-frame-loading");
    const state = reactive({
      isWarning: false,
      hasNoPermission: false,
      noPermissionText: "暂无权限，请联系管理员后重试",
      warnMessage: "",
    });
    const prefix = useLayoutPrefix();
    const methods = {
      goBack: () => {
        window.history.back();
      },
      refresh: () => {
        location.reload();
      },
      renderLoadingOrWarn: () => {
        if (state.isWarning) {
          return (
            <div class={`${prefix}-layout-frame-warning-back-container`}>
              <img src="https://cdn.yearrow.com/imgs/yunque-images/portal-warn-bg.png" alt="" />
              <p class="py-4 text-16 warning-back-message">{state.warnMessage || "页面加载失败，请刷新"}</p>
              <div class="flex justify-center">
                <el-button onClick={methods.refresh} type="primary">刷新</el-button>
              </div>
            </div>
          );
        }
        if (state.hasNoPermission) {
          return (
            <div class={`${prefix}-layout-frame-warning-back-container`}>
              <img src="https://cdn.yearrow.com/imgs/yunque-images/portal-no-permission.png" alt="" />
              <p class="py-4 text-16 warning-back-message">{state.noPermissionText}</p>
              <el-button onClick={methods.refresh} type="primary">刷新</el-button>
            </div>
          );
        }
        return <LayoutLoadingIcon />;
      },
    };

    onMounted(() => {

    });
    return () => {
      return (
        <div class={ns.b()}>
          {methods.renderLoadingOrWarn()}
        </div>
      );
    };
  },
});
