<template>
  <div class="yq-tree-item yq-tree-node" :class="{ 'yq-tree-first-item': level === 1 }">
    <div
      class="yq-item-title"
      :class="{
        'yq-item-title-disabled': node[disabledProp],
        'yq-item-title-selected': node[valueProp] === selectedValue,
      }"
      :style="{ paddingLeft: `${(props.level - 1) * 0}px` }" @click.stop="_selectRow(node)"
    >
      <el-icon v-if="node.loading" class="yq-tree-icon is-loading">
        <Loading />
      </el-icon>
      <div v-else-if="node.loaded && node.children?.length === 0" class="yq-tree-icon">
        <!-- <Document /> -->
      </div>
      <div
        v-else class="yq-tree-icon"
        @click.stop="expand(node)"
      >
        <img v-if="!node.expanded" src="../icons/icon-plus.svg">
        <img v-else src="../icons/icon-minus.svg">
      </div>
      <RenderRow v-if="selectSlots?.treeitem" :data="node" name="treeitem" />
      <span v-else class="yq-item-title-text">
        {{ node[labelProp] }}
      </span>
    </div>
    <div v-if="node.children && node.children.length && node.expanded" class="item-childen">
      <TreeList
        v-for="(child, i) in node.children"
        ref="treeListRef"
        :key="i" :node="child"
        :level="props.level + 1"
      />
      <div
        v-if="moreEnable && node.hasMore && !node.moreLoading" class="yq-item-childen-more yq-item-title"
        :style="{ paddingLeft: `${props.level * 20 + 20}px` }" @click="_expandMore(node)"
      >
        展开更多
      </div>
      <div
        v-if="moreEnable && node.moreLoading" class="yq-item-childen-more yq-item-title"
        :style="{ paddingLeft: `${props.level * 20 + 20}px` }"
      >
        加载中...
      </div>
    </div>
  </div>
</template>

<script lang="ts" setup>
import { Loading } from "@element-plus/icons-vue";
import { inject, ref } from "vue";
import { RenderRow } from "./render-row";
import { DefaultProps, TreeNode } from "./type";

defineOptions({
  name: "TreeList",
  inheritAttrs: false,
});
const props = withDefaults(defineProps<Props>(), {
  node: () => {
    return {};
  },
  level: 1,
  expandFirst: false,
});
export interface Props {
  node: TreeNode;
  level: number;
}
interface SelectSlots {
  treeitem?: object;
}
interface loadFunc {
  (node: TreeNode, resolve: (arr: TreeNode[]) => void): void;
}
interface selectRowFunc {
  (node: TreeNode): void;
}
interface resetPopoverHeightFunc {
  (): void;
}
const selectRow: selectRowFunc | undefined = inject("selectRow");
const defaultProps: DefaultProps = inject("defaultProps") || {};
const currentSize: number = inject("currentSize") || 10;
const loadNode: loadFunc | undefined = inject("loadNode");
const selectSlots: SelectSlots = inject("selectSlots") || {};
const moreEnable = inject("moreEnable");
const selectedValue = inject("selectedValue");
const resetPopoverHeight: resetPopoverHeightFunc | undefined = inject("resetPopoverHeight");
const labelProp = defaultProps.label || "";
const disabledProp = defaultProps.disabled || "";
const valueProp = defaultProps.value || "";
const treeListRef = ref();

async function expand(node: TreeNode) {
  if (node.loaded) {
    node.expanded = !node.expanded;
    return;
  }
  node.loading = true;
  if (!node.children) {
    node.children = [];
  }
  node.limit = currentSize + 1;
  node.offset = 0;
  if (loadNode) {
    loadNode(node, (arr: TreeNode[]) => {
      if (arr.length > currentSize && moreEnable) {
        node.hasMore = true;
        node.children = arr.slice(0, arr.length - 1);
      } else {
        node.children = arr;
      }
      node.loading = false;
      node.expanded = true;
      node.loaded = true;
      if (resetPopoverHeight) {
        resetPopoverHeight();
      }
    });
  }
}
async function _expandMore(node: TreeNode) {
  // 回调函数中处理数据
  if (loadNode) {
    if (!node.offset) {
      node.offset = 0;
    }
    node.offset += currentSize;
    node.moreLoading = true;
    loadNode(node, (arr: TreeNode[]) => {
      node.moreLoading = false;
      if (!node.children) {
        node.children = [];
      }
      if (arr.length <= currentSize) {
        node.hasMore = false;
        node.children.push(...arr);
      } else {
        node.children.push(...arr.slice(0, arr.length - 1));
      }
      if (resetPopoverHeight) {
        resetPopoverHeight();
      }
    });
  }
}
function _selectRow(item: TreeNode) {
  if (selectRow && !item[disabledProp]) {
    selectRow(item);
  }
}
function initFirst(node: TreeNode) {
  if (!node.expanded) {
    expand(node);
  }
}
defineExpose({
  initFirst,
});
</script>
