import { defineComponent, reactive } from "vue";
import { IPublicFramePortalType } from "../../../../types";
import { defaultFrameConfig } from "../../../../utils/default-config";
import { Feedback } from "./feedback";

export const FloatingHelpFeedback = defineComponent({
  name: "FloatingHelpFeedback",
  props: {
    frameStore: {
      type: Object as () => IPublicFramePortalType,
      required: true,
    },
  },
  setup(props) {
    const state = reactive({
      visible: false,
    });
    const methods = {
      openFeedback: () => {
        window.location.href = `/portal/feedback.html?applicationId=${defaultFrameConfig.workstationAppId}`;
      },
      openFeedbackDialog: () => {
        state.visible = true;
        console.log("open dialog");
      },
      renderDialog: () => {
        if (!state.visible) {
          return null;
        }
        return (
          <el-dialog
            v-model={state.visible}
            title="发送反馈"
            lock-scroll={true}
            destroy-on-close={true}
            close-on-click-modal={false}
            close-on-press-escape={false}
            append-to-body={true}
            z-index={9999}
          >
            <Feedback
              frameStore={props.frameStore}
            />
          </el-dialog>
        );
      },
    };
    return () => {
      return (
        <>
          {methods.renderDialog()}
          <el-popover
            placement="left"
            width={350}
          >
            {{
              default: () => {
                return (
                  <div class="floating-help-feedback-content">
                    <div class="floating-help-feedback-content__header">
                      <span class="feedback-title">
                        反馈中心
                      </span>
                      <div>
                        <el-link
                          type="primary"
                          onClick={methods.openFeedback}
                        >
                          进入反馈中心
                        </el-link>
                      </div>
                    </div>
                    <div class="floating-help-feedback-content__tip">
                      您的每一条反馈，都是我们改进的方向
                    </div>
                  </div>
                );
              },
              reference: () => {
                return (
                  <div
                    class="floating-help-feedback layout-floating-item"
                    onClick={methods.openFeedbackDialog}
                  >
                    <el-icon
                      class={["layout-floating-item__icon iconfont icon-a-zu35"]}
                    />
                    <span class="layout-floating-item__title">
                      反馈
                    </span>
                  </div>
                );
              },
            }}
          </el-popover>
        </>
      );
    };
  },
});
