import { isNull } from "./util";

function strictTree(array, optChildren) {
  array.forEach((item) => {
    if (item[optChildren] && !item[optChildren].length) {
      // remove(item, optChildren);
      delete item[optChildren];
    }
  });
}

const treeOptions = {
  parentKey: "parentId",
  key: "id",
  children: "children",
  strict: false,
  sortKey: "sortCode",
  reverse: false,
  data: null,
};

/**
 * 将一个带层级的数据列表转成树结构
 *
 * @param {Array} array 数组
 * @param {object} options {strict: false, parentKey: 'parentId', key: 'id', children: 'children', mapChildren: 'children', data: 'data'}
 * @return {Array}
 */
export function toArrayTree(array, options = {}) {
  const opts = Object.assign({}, treeOptions, options);
  const optStrict = opts.strict;
  const optKey = opts.key;
  const optParentKey = opts.parentKey;
  const optChildren = opts.children;
  // var optMapChildren = opts.mapChildren
  const optSortKey = opts.sortKey;
  const optReverse = opts.reverse || false;
  const optData = opts.data || null;
  const result = [];
  const treeMap = {} as Record<string, any>;
  const idsMap = {};
  let id, treeData, parentId;

  // 排序
  if (optSortKey) {
    // array = orderBy(JSON.parse(JSON.stringify(array)), optSortKey);
    array = JSON.parse(JSON.stringify(array));
    array.sort((a, b) => {
      const v1 = a[optSortKey];
      const v2 = b[optSortKey];

      if (v1 === v2) {
        return 0;
      }

      return v1 && v1.localeCompare ? v1.localeCompare(v2) : v1 > v2 ? 1 : -1;
    });
    if (optReverse) {
      array = array.reverse();
    }
  }

  // 唯一键映射
  array.forEach((item) => {
    id = item[optKey];
    idsMap[id] = true;
  });

  array.forEach((item) => {
    id = item[optKey];

    if (optData) {
      treeData = {};
      treeData[optData] = item;
    } else {
      treeData = item;
    }

    parentId = item[optParentKey];
    treeMap[id] = treeMap[id] || [];
    treeData[optKey] = id;
    treeData[optParentKey] = parentId;

    if (id === parentId) {
      parentId = null;
      console.log("Fix infinite Loop.", item);
    }

    treeMap[parentId] = treeMap[parentId] || [];
    treeMap[parentId].push(treeData);
    treeData[optChildren] = treeMap[id];
    /* if (optMapChildren) {
      treeData[optMapChildren] = treeMap[id]
    } */

    if (!optStrict || (optStrict && isNull(parentId))) {
      if (!idsMap[parentId]) {
        result.push(treeData);
      }
    }
  });

  if (optStrict) {
    strictTree(array, optChildren);
  }

  return result;
}
