import { defineComponent } from "vue";
import { IPublicFramePortalType } from "../../../types";

export const FloatingDocument = defineComponent({
  name: "FloatingDocument",
  props: {
    frameStore: {
      type: Object as () => IPublicFramePortalType,
      required: true,
    },
  },
  setup() {
    return () => {
      return (
        <div class="floating-document layout-floating-item">
          <el-icon class={["layout-floating-item__icon iconfont icon-article-line"]} />
          <span class="layout-floating-item__title">
            文档
          </span>
        </div>
      );
    };
  },
});
