import { webFrameworkEvent } from "../../../../utils/web-framework-event";
import { PluginInstance } from "../../plugin-manage/plugin-type";

/**
 * 插件点击处理
 * @param {PluginInstance} plugin 插件实例
 * @param {Event} e
 */
export function handlePluginClick(plugin: PluginInstance | null, e: Event) {
  if (!plugin) {
    return;
  }
  e.stopPropagation();

  // 触发全局事件
  webFrameworkEvent.emit(`plugin.click.${plugin.id}`, plugin);

  // 调用插件自身的点击处理
  if (plugin.config?.onClick) {
    plugin.config?.onClick(plugin.id);
  }
}

export function useLayoutPrefix() {
  return `portal`;
}
