import type { PropType } from "vue";
import type { IPublicFramePortalType } from "../../types";
import { defineComponent, h } from "vue";
import { useCsNamespace } from "../../hooks/use-namespace";
import "./kanban-layout-container-styles.less";

export const KanbanLayoutContent = defineComponent({
  name: "KanbanLayoutContent",
  props: {
    frameStore: {
      type: Object as () => IPublicFramePortalType,
      required: true,
    },
    rootComponent: {
      type: Object as PropType<any>,
      required: true,
    },
  },
  setup(props) {
    const ns = useCsNamespace("layout-content");

    const methods = {
      renderContent: () => {
        return (
          <div class={ns.e("frame-canvas")}>
            <div class={ns.e("frame-stage")}>
              <div class={ns.e("frame-view")}>
                {h(props.rootComponent)}
              </div>
            </div>
          </div>
        );
      },
    };

    return () => {
      return (
        <div class={ns.b()}>
          {methods.renderContent()}
        </div>
      );
    };
  },
});
