import type { PropType } from "vue";
import type { PluginManager } from "../../plugins/layout-plugin/plugin-manage/plugin-manager";
import { defineComponent, onMounted, onUnmounted, ref } from "vue";
import { useCsNamespace } from "../../hooks/use-namespace";
import { initKanbanPortal } from "../../kanban-web-context";
import { portalStore } from "../../stores";
import { LayoutHeader } from "../layout-header";

import { KanbanLayoutContent } from "./kanban-layout-content";
import { LayoutFrameLoading } from "./layout-frame-loading";

export const KanbanLayoutContainer = defineComponent({
  name: "KanbanLayoutContainer",
  props: {
    pluginManager: {
      type: Object as PropType<PluginManager>,
      required: true,
    },
    rootComponent: {
      type: Object as PropType<any>,
      // required: true,
    },
  },
  setup(props) {
    const ns = useCsNamespace("layout-container");
    const frameStore = portalStore() as any;
    const loaded = ref<boolean>(false);

    // ResizeObserver 实例：观察 body 尺寸变化
    let resizeObserver: ResizeObserver | null = null;

    // 响应式变量：存储 body 宽度和屏幕尺寸状态
    const bodyWidth = ref(document.body.clientWidth);
    const screenSize = ref(""); // 'large' | 'medium' | 'small'

    const methods = {
      init: async () => {
        // 上下文初始化
        loaded.value = await initKanbanPortal();

        // 初始化尺寸状态
        methods.updateScreenSize();

        // 创建 ResizeObserver 并观察 body
        resizeObserver = new ResizeObserver(methods.updateScreenSize);
        resizeObserver.observe(document.body);
      },
      updateScreenSize: () => {
        bodyWidth.value = document.body.clientWidth;

        if (bodyWidth.value >= 1200) {
          screenSize.value = "large";
        } else if (bodyWidth.value >= 992) {
          screenSize.value = "medium";
        } else {
          screenSize.value = "small";
        }

        document.body.setAttribute("data-screen-size", screenSize.value);
      },
    };

    onMounted(() => {
      methods.init();
    });

    onUnmounted(() => {
      // 组件卸载时，停止观察以避免内存泄漏
      if (resizeObserver) {
        resizeObserver.unobserve(document.body);
        resizeObserver.disconnect();
      }
    });

    return () => {
      if (!loaded.value) {
        return (
          <LayoutFrameLoading
            pluginManager={props.pluginManager}
          />
        );
      }
      return (
        <div class={ns.b()}>
          {/* header区域 */ }
          <div class={[ns.e("header")]}>
            <LayoutHeader
              pluginManager={props.pluginManager}
              frameStore={frameStore}
            />
          </div>

          {/* 主区域 */ }
          <div class={ns.e("main")}>
            {/* 可是区域渲染 */ }
            <KanbanLayoutContent
              frameStore={frameStore}
              rootComponent={props.rootComponent}
            />
          </div>
        </div>
      );
    };
  },
});
