/**
 * useTheme —— 主题切换组合式 API
 * --------------------------------------------------
 * 基于 themeManager 封装，对外暴露响应式的主题状态与操作方法。
 *
 * 用法示例：
 * ```ts
 * import { useKanbanTheme } from "@/hooks/use-kanban-theme";
 *
 * const { currentTheme, isDark, setTheme, toggle, themeList } = useKanbanTheme();
 *
 * // 切换到深色
 * setTheme("dark");
 * // 在 light/dark 间切换
 * toggle();
 * ```
 *
 * 注意：
 *  - 多次调用 useTheme 共享同一份全局状态（currentTheme 为响应式 ref）；
 *  - 建议在应用入口处先调用 initTheme() 完成初始化与持久化恢复。
 */

import type { ThemeVars } from "../../styles/theme";
import { ref } from "vue";
import { themeManager } from "../../styles/theme";

/** 全局响应式当前主题（跨组件共享） */
const currentTheme = ref(themeManager.getCurrentTheme());

/** 全局响应式是否深色（跨组件共享） */
const isDark = ref(themeManager.isDark());

/** 全局主题列表 */
const themeList = ref<string[]>(themeManager.getThemeList());

/** 标记是否已注册过全局监听，避免重复注册 */
let globalListenerRegistered = false;

function ensureGlobalListener() {
  if (globalListenerRegistered) {
    return;
  }
  globalListenerRegistered = true;

  // 防御性初始化：确保主题已从 localStorage 恢复（模块级自动初始化的兜底）
  // init() 内部有 initialized 标志位保护，重复调用安全无副作用
  themeManager.init();

  // 同步当前主题状态到响应式 ref
  currentTheme.value = themeManager.getCurrentTheme();
  isDark.value = themeManager.isDark();

  themeManager.onChange((theme) => {
    currentTheme.value = theme;
    isDark.value = theme === "dark";
    themeList.value = themeManager.getThemeList();
  });
}

export function useKanbanTheme() {
  // 确保全局监听只注册一次
  ensureGlobalListener();

  /**
   * 设置主题（带水波纹过渡动画）。
   * @param theme  主题名
   * @param event  鼠标事件（水波纹扩散起点），不传则从屏幕中心扩散
   */
  const setTheme = (theme: string, event?: MouseEvent) => {
    themeManager.setThemeWithTransition(theme, event);
  };

  /**
   * 在 light/dark 之间切换（带水波纹过渡动画）。
   * @param event 鼠标事件（水波纹扩散起点），不传则从屏幕中心扩散
   */
  const toggle = (event?: MouseEvent) => {
    themeManager.toggle(event);
  };

  /** 注册自定义主题 */
  const registerTheme = (name: string, vars: ThemeVars) => {
    themeManager.register(name, vars);
    themeList.value = themeManager.getThemeList();
  };

  return {
    /** 当前主题名（响应式） */
    currentTheme,
    /** 是否深色主题（响应式） */
    isDark,
    /** 已注册主题列表（响应式） */
    themeList,
    /** 设置主题 */
    setTheme,
    /** light/dark 切换 */
    toggle,
    /** 注册自定义主题 */
    registerTheme,
  };
}

/**
 * 初始化主题（应用入口调用一次）。
 * 会从 localStorage 恢复上次主题并应用到 DOM。
 * @param theme 可选，指定初始主题（优先级高于 localStorage）
 */
export function initTheme(theme?: string) {
  themeManager.init(theme);
  currentTheme.value = themeManager.getCurrentTheme();
  isDark.value = themeManager.isDark();
}

export type UseKanbanThemeReturn = ReturnType<typeof useKanbanTheme>;
