import { defineComponent } from "vue";
import { IPublicFramePortalType } from "../../../types";
import { nodeIconClass } from "./icon-util";
import { PortalOrgSelect } from "./portal-org-select";
import "./tenant-org-style.less";

export const TenantOrgWidget = defineComponent({
  name: "TenantOrgWidget",
  props: {
    frameStore: {
      type: Object as () => IPublicFramePortalType,
      required: true,
    },
  },
  setup(props) {
    return () => {
      return (
        <div class="layout-header-tenant-org">
          <i class={nodeIconClass(props.frameStore.$context.extType)}></i>
          <div class="layout-header-tenant-org__top">
            <span class="layout-header-tenant-org--platform__title">
              组织架构：
            </span>
            <PortalOrgSelect
              class="layout-header-tenant-org__org-search"
              frameStore={props.frameStore}
            />
          </div>
        </div>
      );
    };
  },
});
