import type { Router } from "vue-router";
import { onActivated, onMounted } from "vue";
import { portalStore } from "../stores";

interface PageParams {
  isForceFlush?: boolean; // 强制刷新，默认值true
  rootPath?: string; // 根路由，默认值 '/'
}

/**
 * 页面加载钩子
 * @param router
 * @param params
 */
export function usePageLoadHook(router: Router, params?: PageParams): void {
  const portal = portalStore();
  const isForceFlush = params?.isForceFlush ?? true;
  const rootPath = params?.rootPath ?? "/";
  onActivated(() => {
    if (isForceFlush && router && router.currentRoute.value.path !== rootPath && !portal.isRefresh) {
      router.replace({ path: rootPath });
    }
  });

  const commitRefresh = (): void => {
    if (!portal.isRefresh) {
      setTimeout(() => {
        portal.setIsRefresh(true);
      }, 100);
    }
  };
  const initPage = (): void => {
    commitRefresh();
  };
  onMounted(initPage);
}
