import type { Placement } from "element-plus";
import type { Component, VNode } from "vue";
// 插件类型枚举
export enum PluginType {
  TEXT = "text",
  ICON_EXPAND = "icon-expand",
  ICON_DROPDOWN = "icon-dropdown",
  ICON_DRAWER = "icon-drawer",
  ICON_LINK = "icon-link",
  CUSTOM_RENDER = "custom-render",
}

// 插件位置枚举
export const pluginPosition = {
  HEADER_LEFT: Symbol("header-left"),
  HEADER_CENTER: Symbol("header-center"),
  HEADER_RIGHT: Symbol("header-right"),
  FLOATING_HELP: Symbol("floating-help"),
  SIDEBAR_LEFT: Symbol("sidebar-left"),
} as const;

export type PluginPosition = keyof typeof pluginPosition;

/**
 * 插件位置枚举值
 */
export type PluginPositionKey = typeof pluginPosition[keyof typeof pluginPosition];

// 插件基础配置
export interface PluginBaseConfig {
  id: string;
  type: PluginType;
  position: PluginPositionKey;
  visible?: boolean;
  sort?: number;
  onClick?: (...args: any[]) => void;
  description?: string;
  [key: string]: any;
  extra?: Record<string, any>;
}

// 文字插件配置
export interface TextPluginConfig extends PluginBaseConfig {
  type: PluginType.TEXT;
  text: string | Component | VNode;
}

// 图标插件基础配置
export interface IconPluginBaseConfig extends PluginBaseConfig {
  icon: Component | VNode;
  tooltip?: string;
  placement?: Placement;
}

// 图标+下拉框插件配置
export interface IconDropdownPluginConfig extends IconPluginBaseConfig {
  type: PluginType.ICON_DROPDOWN;
  items: {
    label: string;
    key: string;
    onClick: () => void;
  }[];
}

// 图标+抽屉插件配置
export interface IconDrawerPluginConfig extends IconPluginBaseConfig {
  type: PluginType.ICON_DRAWER;
  title: string;
  component: () => VNode | Component;
  width?: string | number;
  direction?: "ltr" | "rtl" | "ttb" | "btt";
}

// 图标+链接插件配置
export interface IconLinkPluginConfig extends IconPluginBaseConfig {
  type: PluginType.ICON_LINK;
  url: string;
  target?: "_blank" | "_self" | "_parent" | "_top";
}

export interface CustomRenderPluginConfig extends PluginBaseConfig {
  type: PluginType.CUSTOM_RENDER;
  renderComponent: () => VNode | Component;
}

// 所有插件配置类型
export type PluginConfig
  = | CustomRenderPluginConfig
    | TextPluginConfig
    | IconDropdownPluginConfig
    | IconDrawerPluginConfig
    | IconLinkPluginConfig;

// 插件实例接口
export interface PluginInstance {
  id: string;
  config: PluginConfig;
  component: Component;
}
