import type { QueryParamsType } from "../types";
import { isEmpty, omit, pick } from "lodash-es";
import { customConfigManagerPlugin } from "../plugins";
import { urlUtil } from "./url-parser";
import { decimalAndBase36, encryptParams } from "./util";

export const queryKeys = ["applicationId", "moduleId", "orgId"];

/**
 * 格式化参数
 * @description 格式化参数，将参数转换为 36进制 和 10进制
 * @param {QueryParamsType} queryParams
 * @returns {{encryption: QueryParamsType, params: QueryParamsType, pathname: string}}
 */
export function formatQueryParams(queryParams: QueryParamsType) {
  const result = {
    encryption: {} as QueryParamsType, // 36进制
    params: {} as QueryParamsType, // 10 进制
    pathname: location.pathname,
  };
  const query = pick(queryParams, queryKeys) as QueryParamsType;
  if (query.applicationId) {
    const { decimal, base36 } = decimalAndBase36(query.applicationId as string);
    result.params.applicationId = decimal;
    result.encryption.applicationId = base36;
  }

  if (query.moduleId) {
    const { decimal, base36 } = decimalAndBase36(query.moduleId as string);
    result.params.moduleId = decimal;
    result.encryption.moduleId = base36;
  }

  if (query.orgId) {
    const { decimal, base36 } = decimalAndBase36(query.orgId as string);
    result.params.orgId = decimal;
    result.encryption.orgId = base36;
  }

  return result;
}

/**
 * 跳转url
 * @param {QueryParamsType & {url: string}} params
 * @returns {string}
 */
export function redirectUrl(params: QueryParamsType & { url: string }) {
  const formatParams = formatQueryParams(params);
  if (!params.applicationId) {
    throw new Error("缺少applicationId参数");
  }

  const parserQuery = urlUtil.extractUrlParams<QueryParamsType, any>(location.href);

  // 低代码自定义不重新刷新请求
  const otherKeys = omit(parserQuery.searchParams, queryKeys);
  // 不忽略url中search参数
  const otherParams = (!isEmpty(otherKeys) && !customConfigManagerPlugin.ignoreOtherQueryParams) ? `&${urlUtil.stringify(otherKeys)}` : "";
  return `${params.url}?${encryptParams(formatParams.params)}${otherParams}`;
}
