import type { QueryParamsType } from "../../types";
import type { configApiMapKeyType } from "./custom-config-manager-types";
import { apiCustomConfig } from "../../api/api-custom-config";

export class CustomConfigManagerPlugin {
  private static instance: CustomConfigManagerPlugin;
  private constructor() {
  }

  public static getInstance(): CustomConfigManagerPlugin {
    if (!CustomConfigManagerPlugin.instance) {
      CustomConfigManagerPlugin.instance = new CustomConfigManagerPlugin();
    }
    return CustomConfigManagerPlugin.instance;
  }

  /**
	 * 自定义配置接口映射，外部支持自定义查询接口
	 * @private
	 */
  private configApiMap: configApiMapKeyType = apiCustomConfig;

  public get customConfigApiMap(): configApiMapKeyType {
    return this.configApiMap;
  }

  /**
	 * 设置自定义配置接口
	 * 请在框架初始化之前修改
	 * @param value
	 */
  public set customConfigApiMap(value: configApiMapKeyType) {
    Object.assign(this.configApiMap, value);
  }

  /**
	 * 低代码设置自定义查询查询参数
	 * @type {QueryParamsType | null}
	 * @private
	 */
  private _queryParams: QueryParamsType | null = null;

  get queryParams(): QueryParamsType | null {
    return this._queryParams;
  }

  set queryParams(value: QueryParamsType | null) {
    this._queryParams = value;
  }

  /**
	 * 忽略其他查询参数
	 * @type {boolean}
	 * @private
	 */
  private _ignoreOtherQueryParams = true;

  get ignoreOtherQueryParams(): boolean {
    return this._ignoreOtherQueryParams;
  }

  set ignoreOtherQueryParams(value: boolean) {
    this._ignoreOtherQueryParams = value;
  }
}

export const customConfigManagerPlugin = CustomConfigManagerPlugin.getInstance();
