import { defineComponent } from "vue";
import { useCsNamespace } from "../../hooks";
import loadingSvg from "./loading-svg.svg";
import "./layput-loading-icon-style.less";

export const LayoutLoadingIcon = defineComponent({
  name: "LayoutLoadingIcon",
  props: {},
  setup() {
    const ns = useCsNamespace("layout-loading-icon");

    return () => {
      return (
        <div class={ns.b()}>
          <div class={ns.e("loading")}>
            <img src={loadingSvg} alt="" />
          </div>
          <span class={ns.e("loading-text")}>加载中</span>
        </div>
      );
    };
  },
});
