/**
 * 判断是否为Null
 *
 * @param {object} obj 对象
 * @return {boolean}
 */
export function isNull(obj) {
  return obj === null;
}

/**
 * 在当前应用中打开模块
 * @param menu
 * @param {boolean} isNewTab
 */
export function openCurAppModule(menu: IPublicMenuType, isNewTab = false) {
  if (isEmpty(menu)) {
    console.log("menu empty");
    console.warn("menu is not exist");
    return;
  }
  const frameStore = portalStore();

  // const queryParams = `?applicationId=${frameStore.$context.applicationId}&orgId=${frameStore.$context.orgId}&moduleId=${menu.moduleId}`;
  const queryParams = encryptParams({
    applicationId: frameStore.$context.applicationId,
    orgId: `${frameStore.$context.orgId}`,
    moduleId: menu.moduleId,
  });
  const openUrl = `${menu.moduleUrl}?${queryParams}`;
  if (isNewTab) {
    window.open(openUrl);
  } else {
    window.location.href = openUrl;
  }
}

/**
 * 检测数字进制
 * @description 检测输入的数字字符串是10进制还是36进制
 * @param strNum 待检测的数字字符串或数字
 * @returns {boolean}
 *  - true: 10进制（仅包含数字0-9）
 *  - false: 36进制（包含字母a-z或其他非法字符）或空值
 * @throws {Error} 当输入为空字符串（去除空白后）时抛出错误
 * @example
 *  detect10Base('123')      // true  - 10进制
 *  detect10Base('abc')      // false - 36进制
 *  detect10Base('1a2')      // false - 36进制
 *  detect10Base(null)       // false - 空值
 *  detect10Base('')         // 抛出错误
 */
export function detect10Base(strNum?: unknown): boolean {
  // 处理空值：null、undefined、0、false 等
  if (strNum === null || strNum === undefined) {
    return false;
  }

  // 特殊处理数字0和布尔值false（转为字符串后都是有效的）
  if (strNum === 0 || strNum === false) {
    return true; // 0 是有效的10进制数字
  }

  // 处理空字符串（包括空白字符）
  if (strNum === "" || (typeof strNum === "string" && strNum.trim() === "")) {
    throw new Error("输入的字符串不能为空");
  }

  // 转换为字符串并去除首尾空白
  const str = String(strNum).trim();

  // 再次检查是否为空（防止转换后为空）
  if (str === "") {
    throw new Error("输入的字符串不能为空");
  }

  // 处理负数：移除负号后检测
  const numStr = str.startsWith("-") ? str.slice(1) : str;

  // 检查移除负号后是否为空
  if (numStr === "") {
    return false; // 单独的 '-' 不是有效数字
  }

  // 10进制规则：只能包含数字0-9
  const is10Base = /^[0-9]+$/.test(numStr);

  // 如果匹配10进制规则，返回 true
  // 否则返回 false（可能是36进制或包含非法字符）
  return is10Base;
}

/**
 * 大整数进制转换工具
 */
export const BigIntRadix = {
  /**
	 * 十进制字符串转任意进制
	 */
  encode(decStr, radix = 36) {
    return BigInt(decStr).toString(radix);
  },

  /**
	 * 任意进制转十进制字符串
	 */
  decode(encodedStr, radix = 36) {
    return [...encodedStr].reduce((acc, char) =>
      acc * BigInt(radix) + BigInt(Number.parseInt(char, radix)), 0n).toString();
  },
};

/**
 * 十进制和36进制转换
 * @param {string | number} num
 * @returns {{decimal: string, base36: string}}
 */
export function decimalAndBase36(num: string | number) {
  const data = `${num}`;
  const result = {
    decimal: "0",
    base36: "",
  };

  // 十进制
  if (detect10Base(data)) {
    result.decimal = data;
    result.base36 = BigIntRadix.encode(data, 36);
    // result.base36 = (parseInt(data, 10)).toString(36);
  } else { // 36进制
    // result.decimal = `${ parseInt(data, 36) }`;
    result.decimal = BigIntRadix.decode(data);
    result.base36 = data;
  }

  return result;
}

/**
 * 加密URL参数
 * @param {QueryParamsType} ctxResult 10进制参数
 * @returns {string} 36进制加密参数
 */
export function encryptParams(ctxResult: QueryParamsType) {
  const applicationId36 = BigIntRadix.encode(ctxResult.applicationId, 36);
  const moduleId36 = BigIntRadix.encode(ctxResult.moduleId, 36);
  const orgId36 = BigIntRadix.encode(ctxResult.orgId, 36);
  return `applicationId=${applicationId36}&moduleId=${moduleId36}&orgId=${orgId36}`;
}
