import { defineComponent } from "vue";
import { useCsNamespace } from "../../../hooks/use-namespace";
import { IPublicFramePortalType } from "../../../types";
import "./application-name-widget.style.less";

export const ApplicationNameWidget = defineComponent({
  name: "ApplicationNameWidget",
  props: {
    frameStore: {
      type: Object as () => IPublicFramePortalType,
      required: true,
    },
  },
  setup(props) {
    const ns = useCsNamespace("application-name-widget");
    return () => {
      return (
        <div class={ns.b()}>
          {props.frameStore.$context.appName}
        </div>
      );
    };
  },
});
