// import { snapdom } from "@zumer/snapdom";
import { domToPng } from "modern-screenshot";
import { defineComponent, onMounted, reactive } from "vue";
import { IPublicFramePortalType } from "../../../../types";
import "./feedback.less";

export const Feedback = defineComponent({
  name: "Feedback",
  props: {
    frameStore: {
      type: Object as () => IPublicFramePortalType,
      required: true,
    },
  },
  setup(props) {
    const issueTypeOptions = [
      {
        value: "feature",
        label: "功能建议",
      },
      {
        value: "bug",
        label: "BUG反馈",
      },
      {
        value: "other",
        label: "其他",
      },
    ];
    const feedbackState = reactive({
      moduleName: "",
      orgId: null,
      content: "",
      attachments: [],
      userPhone: "",
      userEmail: "",
      menuName: "",
      issueType: "",
    });
    const state = reactive({
      name: "测试",
      imgSrc: "",
    });

    const methods = {
      handleSubmit: () => {
        console.log("提交反馈");
        console.log(JSON.stringify(feedbackState));
      },
      openImage: () => {
        const base64Str = state.imgSrc;
        const newTab = window.open("about:blank");
        if (!newTab) {
          console.error("Failed to open new tab");
          return;
        }
        newTab.document.write(`<img src="${base64Str}" style="max-width:100%;max-height:100vh;margin:0 auto;display:block;">`);
        newTab.document.close();
      },
      takeScreenshot: (): Promise<{ url: string; key: string } | null> => {
        return new Promise((resolve) => {
          const screenshotKey = `屏幕截图-${Date.now()}`;
          domToPng(document.querySelector("html")!, {
            debug: true,
            progress: (current, total) => {
              console.log(`${current}/${total}`);
            },
          }).then((dataUrl) => {
            resolve({
              url: dataUrl,
              key: screenshotKey,
            });
          }).catch((error) => {
            console.error("oops, something went wrong!", error);
            resolve(null);
          });
        });
      },
    };

    onMounted(() => {
      feedbackState.moduleName = props.frameStore.$context.moduleName;
      feedbackState.userPhone = props.frameStore.$context.phoneNumber || "";
      methods.takeScreenshot().then((screenshot) => {
        if (screenshot?.url) {
          state.imgSrc = screenshot.url;
        }
      });
    });
    return () => {
      return (
        <div class="feedback-container">
          <el-form label-width="125px" label-position="top">
            <el-row gutter={10}>
              <el-col span={24}>
                <el-form-item label="所属页面">
                  <el-input v-model={feedbackState.moduleName} placeholder="placeholder" />
                </el-form-item>
              </el-col>
              <el-col span={12}>
                <el-form-item label="问题类型">
                  <el-select v-model={feedbackState.issueType} placeholder="问题类型">
                    {
                      issueTypeOptions.map((item) => {
                        return (
                          <el-option
                            key={item.value}
                            label={item.label}
                            value={item.value}
                          >
                          </el-option>
                        );
                      })
                    }
                  </el-select>
                </el-form-item>
              </el-col>
              <el-col span={12}>
                <el-form-item label="紧急程度">
                  <el-input v-model={state.name} placeholder="placeholder" />
                </el-form-item>
              </el-col>
              <el-col span={24}>
                <el-form-item label="描述当前的情况">
                  <el-input v-model={state.name} placeholder="placeholder" />
                </el-form-item>
              </el-col>
              <el-col span={24}>
                <el-form-item label="截图或上传附件">
                  <div style={{ width: "160px", height: "160px" }}>
                    <img
                      src={state.imgSrc}
                      alt="当前页面截图"
                      width={220}
                      height={165}
                      onClick={methods.openImage}
                    />
                  </div>
                </el-form-item>
              </el-col>
              <el-col span={24}>
                <el-form-item label="你可以就此反馈与我联系">
                  <el-row gutter={10}>
                    <el-col span={12}>
                      <el-input v-model={feedbackState.userPhone} placeholder="手机号" />
                    </el-col>
                    <el-col span={12}>
                      <el-input v-model={feedbackState.userEmail} placeholder="请输入电子邮件" />
                    </el-col>
                  </el-row>
                </el-form-item>
              </el-col>
            </el-row>
          </el-form>
          <div class="feedback-footer">
            <el-button type="primary" onClick={methods.handleSubmit}>提交反馈</el-button>
          </div>
        </div>
      );
    };
  },
});
