import { defineComponent, PropType } from "vue";
import { webFrameworkEvent } from "../../../../utils/web-framework-event";
import { TextPluginConfig } from "../plugin-type";

export default defineComponent({
  name: "PluginText",
  props: {
    config: {
      type: Object as PropType<TextPluginConfig>,
      required: true,
    },
  },
  setup(props) {
    const handleClick = () => {
      // 触发点击事件
      webFrameworkEvent.emit(`plugin.${props.config.id}.click`);
      // 调用配置中的点击回调
      if (props.config.onClick) {
        props.config.onClick();
      }
    };

    return () => (
      <div onClick={handleClick}>
        {props.config.text}
      </div>
    );
  },
});
