import type { ModuleCustomConfigStoreType, RefreshTypeParams } from "./module-custom-config-type";
import { merge } from "lodash-es";
import { defineStore } from "pinia";
import { reactive, ref } from "vue";
import { customConfigManagerPlugin } from "../../plugins";
import { webFrameworkEvent } from "../../utils/web-framework-event";
import { portalStore } from "../portal";

export const moduleCustomConfigStore = defineStore("moduleCustomConfig", (): ModuleCustomConfigStoreType => {
  const frameStore = portalStore();
  const apiConfigMap = customConfigManagerPlugin.customConfigApiMap;
  const exportConfigs = ref([]);
  const printConfigs = ref([]);
  const tableConfigs = ref({});
  const formConfigs = ref({});
  const filterConfigs = ref({});
  const descriptionConfigs = ref({});
  const loading = ref(false);
  const customConfigPanel = reactive({
    descriptionConfigs: [],
    exportConfigs: [],
    filterConfigs: [],
    formConfigs: [],
    printConfigs: [],
    tableConfigs: [],
  });

  /**
	 * 设置自定义数据
	 * @param val
	 */
  const setExportConfigs = (val): void => {
    exportConfigs.value = val;
  };
  const setPrintConfigs = (val): void => {
    printConfigs.value = val;
  };
  const setTableConfigs = (val): void => {
    const tableObj = {};
    val.forEach((item) => {
      tableObj[item.code] = item;
    });
    tableConfigs.value = tableObj;
  };
  const setFormConfigs = (val): void => {
    const obj = {};
    val.forEach((item) => {
      obj[item.code] = item;
    });
    formConfigs.value = obj;
  };
  const setFilterConfigs = (val): void => {
    const obj = {};
    val.forEach((item) => {
      obj[item.code] = item;
    });
    filterConfigs.value = obj;
  };
  const setDescriptionConfigs = (val): void => {
    const obj = {};
    val.forEach((item) => {
      obj[item.code] = item;
    });
    descriptionConfigs.value = obj;
  };
  const setCustomConfigPanel = (val): void => {
    for (const key in val) {
      if (Object.hasOwn(val, key)) {
        const cusItem = val[key];
        cusItem.forEach((item) => {
          item.mainPermissionJson = JSON.parse(item.mainPermissionJson);
        });
      }
    }
    merge(customConfigPanel, val);
  };

  // 1.初始化模块自定义配置
  const initCustomConfig = async (): Promise<void> => {
    const { moduleId, tenantId, fullId, userId } = frameStore.$context;
    loading.value = true;

    const params = {
      moduleId,
      tenantId,
      orgFullId: fullId,
      userId,
    };
    apiConfigMap.getModuleCustomConfig(params).then((result) => {
      loading.value = false;
      if (result.status === "success" && result.result) {
        setTableConfigs(result.result.tableConfigs);
        setFormConfigs(result.result.formConfigs);
        setFilterConfigs(result.result.filterConfigs);
        setDescriptionConfigs(result.result.descriptionConfigs);
      }
      webFrameworkEvent.emit("onCustomConfigLoaded", result.result);
    }).catch((error) => {
      console.log(error);
      loading.value = false;
    });
  };

  // 2.初始化模块导出配置
  const initExportConfig = async (): Promise<void> => {
    const { moduleId, tenantId, fullId, userId } = frameStore.$context;
    const params = {
      moduleId,
      tenantId,
      orgFullId: fullId,
      userId,
    };
    const result = await apiConfigMap.getExportConfig(params);
    if (result.status === "success" && result.result) {
      setExportConfigs(result.result.exportConfigs);
      setPrintConfigs(result.result.printConfigs);
    }
  };

  // 3.获取用户自定义配置信息（自定义配置面板是否显示）
  const initCustomConfigPanel = async (): Promise<void> => {
    const { moduleId, tenantId, fullId, userId } = frameStore.$context;
    const params = {
      moduleId,
      tenantId,
      orgFullId: fullId,
      userId,
      level: 3,
    };
    const result = await apiConfigMap.getCustomPanel(params);
    if (result.status === "success" && result.result) {
      setCustomConfigPanel(result.result);
    }
  };
  /**
	 * 重置当前页面的所有模块自定义配置，
	 * 包括：表格配置、打印配置、导出配置
	 */
  const resetConfig = async (refreshType: RefreshTypeParams = "all"): Promise<void> => {
    // eslint-disable-next-line ts/no-use-before-define
    await initModuleCustomConfig(refreshType);
  };

  /**
	 * 初始化页面配置
	 */
  const initModuleCustomConfig = async (refreshType: RefreshTypeParams = "all"): Promise<void> => {
    const isAll = refreshType === "all";
    const refreshTypes = typeof refreshType === "string" ? [refreshType] : refreshType;
    if (isAll || refreshTypes.includes("custom")) {
      initCustomConfig();
    }
    if (isAll || refreshTypes.includes("export")) {
      initExportConfig();
    }
    if (isAll || refreshTypes.includes("panel")) {
      initCustomConfigPanel();
    }
  };

  return {
    exportConfigs,
    printConfigs,
    tableConfigs,
    formConfigs,
    filterConfigs,
    descriptionConfigs,
    loading,
    setExportConfigs,
    setPrintConfigs,
    setTableConfigs,
    setFormConfigs,
    setFilterConfigs,
    setDescriptionConfigs,
    initModuleCustomConfig,
    resetConfig,
    customConfigPanel,
  };
});
