<template>
  <span
    ref="inputRef" class="search-span" :class="$attrs.class"
    @click="_visibleChange"
  >
    <div class="serch-span-text">{{ inputValue }}</div>
    <el-icon style="margin-left: 5px"><ArrowDown /></el-icon>
  </span>
  <el-popover
    :key="listHeight"
    ref="treePopoverRef"
    data-id="demo-uid"
    :visible="visible"
    :virtual-ref="inputRef"
    trigger="click"
    virtual-triggering
    :hide-after="100"
    :width="props.dropdownWidth"
    :popper-class="props.popoverClass"
  >
    <div
      ref="treePopoverContentRef"
      v-click-outside="onClickOutside"
      class="yq-dropdown-content"
      :style="{ maxHeight: props.dropdownHeight }"
      @mouseenter="inputHover = true"
      @mouseleave="inputHover = false"
    >
      <el-input
        v-model="filter"
        class="a-111"
        :class="props.inputClass"
        :placeholder="inputPlaceholder"
        :size="props.size"
        :style="{ display: visible ? 'inline-flex' : 'none', width: '100%' }"
        @input="_filterData"
        @mouseenter="inputHover = true"
        @mouseleave="inputHover = false"
      >
        <template #prefix>
          <el-icon class="func-icon func-icon-disabled">
            <Search />
          </el-icon>
          <template>
            <el-icon
              v-if="clearable && !isSearch && props.modelValue"
              class="func-icon"
              @click.stop="_clear"
            >
              <CircleClose />
            </el-icon>
            <el-icon
              v-if="props.reloadEnable && !isSearch && visible"
              class="func-icon"
              @click.stop="reload"
            >
              <Refresh />
            </el-icon>
            <el-icon
              v-if="isSearch"
              class="func-icon"
              @click.stop="changeSearch(false)"
            >
              <CircleCloseFilled />
            </el-icon>
          </template>
        </template>
      </el-input>
      <SearchList
        v-if="isSearch && visible"
        :list-data="listData"
        :loading="listLoading"
      />
      <TreeList
        v-if="!isSearch && visible"
        ref="treeRef"
        :node="treeData"
        :level="1"
      />
    </div>
  </el-popover>
</template>

<script setup lang="ts">
import {
  ArrowDown,
  CircleClose,
  CircleCloseFilled,
  Refresh,
  Search,
} from "@element-plus/icons-vue";
import { ClickOutside as vClickOutside } from "element-plus";
import {
  computed,
  nextTick,
  provide,
  ref,
  useSlots,
  watch,
  watchEffect,
} from "vue";
import { useLoadTreeFunc } from "./load-tree-hooks";
import SearchList from "./search-list.vue";
import TreeList from "./tree-list.vue";
import { DefaultProps, OrgNodeType, TreeNode } from "./type";

defineOptions({
  name: "SearchTreeSelect",
  inheritAttrs: false,
});

const props = withDefaults(defineProps<Props>(), {
  defaultProps: () => {
    return {
      label: "label",
      value: "id",
      disabled: "disabled",
    };
  },
  // 限制行数
  currentSize: 20,
  placeholder: "",
  searchPlaceholder: "请输入检索信息",
  width: "100%",
  size: "",
  dropdownWidth: "",
  dropdownHeight: "400px",
  rootNode: () => {
    return {
      children: [],
    };
  },
  searchEnable: false,
  clearable: false,
  inputClass: "",
  moreEnable: true,
  expandFirst: true,
  defaultText: "",
  defaultExpandedKeys: () => [],
  reloadEnable: false,
  defaultExpandLastNode: false, // 展开最后一级
  disabled: false,
  popoverClass: "111111",
});

const emits = defineEmits([
  "update:modelValue",
  "loadNode",
  "loadSearchData",
  "selectChange",
  "clear",
  "reload",
]);

export interface Props {
  defaultProps: DefaultProps;
  currentSize?: number;
  modelValue?: string | number;
  placeholder?: string;
  searchPlaceholder?: string;
  width?: string;
  size?: "" | "small" | "large";
  dropdownWidth?: string;
  dropdownHeight?: string;
  rootNode?: OrgNodeType;
  searchEnable?: boolean;
  moreEnable?: boolean;
  clearable?: boolean;
  inputClass?: string;
  expandFirst?: boolean;
  defaultText?: string;
  defaultExpandedKeys?: string[];
  reloadEnable?: boolean;
  defaultExpandLastNode?: boolean;
  disabled?: boolean;
  popoverClass?: string;
}
const slots = useSlots();

provide("defaultProps", props.defaultProps);
provide("currentSize", props.currentSize);
provide("selectSlots", slots);
provide("moreEnable", props.moreEnable);

const inputRef = ref();
const treePopoverRef = ref();
const treeRef = ref();

const filter = ref("");
const isSearch = ref(false);
const visible = ref(false);
const inputHover = ref(false);
const treeData = ref(JSON.parse(JSON.stringify(props.rootNode)));

const listData = ref([]);
const listLoading = ref(false);
const labelValue = ref(props.defaultText);

const rootId = ref(
  props.rootNode[props.defaultProps.value as keyof typeof props.rootNode],
);

const listHeight = ref(0);

watch(
  () => props.defaultText,
  (n) => {
    labelValue.value = n;
  },
);
watch(
  () => props.modelValue,
  (n) => {
    selectedValue.value = n;
  },
);
watch(
  () => props.rootNode,
  (n, o) => {
    const prop = props.defaultProps.value as keyof typeof props.rootNode;
    const nid = n?.[prop];
    const oid = o?.[prop];

    if (nid !== oid) {
      treeData.value = JSON.parse(JSON.stringify(props.rootNode));
      rootId.value = nid;
    }
  },
  { immediate: true, deep: true },
);
const inputValue = computed({
  get() {
    return labelValue.value;
  },
  set(val: string) {},
});
const inputPlaceholder = computed(() => {
  return isSearch.value ? props.searchPlaceholder : props.placeholder;
});

function changeSearch(b: boolean) {
  if (!props.disabled) {
    isSearch.value = b;
    visible.value = b;
    listHeight.value = 0;
    if (b) {
      inputRef.value.focus();
      loadSearchData();
    } else {
      filter.value = "";
    }
  }
}
function _visibleChange() {
  visible.value = !visible.value;
  if (visible.value) {
    resetPopoverHeight();
  }
}
function onClickOutside() {
  if (!inputHover.value) {
    visible.value = false;
    if (isSearch.value) {
      isSearch.value = false;
      filter.value = "";
    }
  }
}
// 选择行
const selectedValue = ref<any>(props.modelValue);
function selectRow(item: TreeNode) {
  emits(
    "update:modelValue",
    item[props.defaultProps.value as keyof typeof item],
  );
  labelValue.value = props.defaultProps.label
    ? item[props.defaultProps.label]
    : "";

  visible.value = false;
  isSearch.value = false;
  filter.value = "";
  selectedValue.value = item[props.defaultProps.value as keyof typeof item];
  emits("selectChange", item);
}

provide("selectRow", selectRow);
provide("selectedValue", selectedValue);
// 加载默认节点
const treePopoverContentRef = ref();
function resetPopoverHeight() {
  nextTick(() => {
    if (treePopoverContentRef.value) {
      const height = treePopoverContentRef.value.offsetHeight + 30;
      // console.log("height", height);
      const dropHei = Number(props.dropdownHeight.replace("px", ""));
      // console.log("dropHei", dropHei);
      if (height <= dropHei && listHeight.value !== height) {
        listHeight.value = height;
        inputHover.value = false;
      }
    }
  });
}
provide("resetPopoverHeight", resetPopoverHeight);
const { loadDefaultNodes, defaultExpandedKeys } = useLoadTreeFunc(
  emits,
  props,
  resetPopoverHeight,
);

function setExpandedKeys(keys) {
  defaultExpandedKeys.value = keys;
  if (
    String(defaultExpandedKeys.value[0])
    === String(
      treeData.value[props.defaultProps.value as keyof typeof props.rootNode],
    )
  ) {
    loadDefaultNodes([treeData.value], 1, treeData.value);
  }
}
watch(
  () => props.defaultExpandedKeys,
  (n, o) => {
    setExpandedKeys(n);
  },
);
// 加载节点
function loadNode(node: object, resolve: (arr: object[]) => void) {
  emits("loadNode", node, resolve);
}

provide("loadNode", loadNode);
// 搜索列表数据加载
function loadSearchData() {
  listLoading.value = true;
  listData.value = [];
  emits("loadSearchData", filter.value, (data: []) => {
    listData.value = data;
    listLoading.value = false;
    resetPopoverHeight();
  });
}
// 输入框过滤
let timer: number = 0;
function _filterData() {
  if (!visible.value) {
    visible.value = true;
  }
  if (filter.value) {
    isSearch.value = true;
  }
  if (timer) {
    clearTimeout(timer);
  }
  timer = window.setTimeout(() => {
    loadSearchData();
  }, 500);
}
// 清除
function _clear() {
  labelValue.value = "";
  selectedValue.value = null;
  emits("update:modelValue", null);
  emits("clear");
}
// 默认加载第一级
const stop = watchEffect(() => {
  if (
    treeRef.value
    && props.expandFirst
    && treeData.value[props.defaultProps.value as keyof typeof props.rootNode]
    && !treeData.value.expanded
  ) {
    if (defaultExpandedKeys.value.length === 0) {
      setExpandedKeys([rootId.value]);
    }
    stop();
  }
});
// 刷新树组件
function reload() {
  treeData.value = JSON.parse(JSON.stringify(props.rootNode));
  emits("reload");
  if (props.expandFirst && defaultExpandedKeys.value.length <= 1) {
    setExpandedKeys([rootId.value]);
  }
}

defineExpose({
  reload,
});
</script>

<style lang="less" scoped>
.search-span {
  border: none; /* 移除边框 */
  box-shadow: none; /* 移除阴影，如有需要 */
  font-size: 14px;
  font-weight: normal;
  position: relative;
  width: auto;
  line-height: 22px;
  letter-spacing: 0;
  gap: 8px;
  height: 60px;
  cursor: pointer;
  display: flex;
  align-items: center;
  padding: 0 12px;
  &.is-active {
    background: transparent !important;
  }

  &:hover {
    background: var(--el-color-primary-dark-2) !important;
    color: #ffffff !important;
  }
}
.serch-span-text {
  display: inline-block;
  max-width: 200px; /* 根据实际容器调整 */
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
</style>
